-- BARBA10 / Supabase PostgreSQL
create extension if not exists pgcrypto;
create extension if not exists citext;
do $$ begin create type public.app_role as enum ('super_admin','tenant_owner','shop_manager','barber','attendant','customer'); exception when duplicate_object then null; end $$;
do $$ begin create type public.appointment_status as enum ('pending','confirmed','completed','cancelled','no_show'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',whatsapp text unique,role public.app_role not null default 'customer',avatar_url text,tenant_id uuid,shop_id uuid,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.tenants(id uuid primary key default gen_random_uuid(),name text not null,slug citext unique not null,owner_id uuid references public.profiles(id) on delete set null,phone text,email citext,logo_url text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shops(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,name text not null,slug citext not null,phone text,address text,city text,state text,opening_time time,closing_time time,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,slug));
alter table public.profiles drop constraint if exists profiles_tenant_id_fkey; alter table public.profiles add constraint profiles_tenant_id_fkey foreign key(tenant_id) references public.tenants(id) on delete set null;
alter table public.profiles drop constraint if exists profiles_shop_id_fkey; alter table public.profiles add constraint profiles_shop_id_fkey foreign key(shop_id) references public.shops(id) on delete set null;
create table if not exists public.staff(id uuid primary key references public.profiles(id) on delete cascade,tenant_id uuid not null references public.tenants(id) on delete cascade,shop_id uuid references public.shops(id) on delete set null,display_name text not null,specialty text,commission_rate numeric(5,2) not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,shop_id uuid references public.shops(id) on delete cascade,name text not null,description text,duration_minutes integer not null default 30 check(duration_minutes>0),price numeric(10,2) not null default 0 check(price>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.customers(id uuid primary key references public.profiles(id) on delete cascade,whatsapp text unique not null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.appointments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,shop_id uuid not null references public.shops(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,barber_id uuid references public.staff(id) on delete set null,service_id uuid not null references public.services(id) on delete restrict,starts_at timestamptz not null,ends_at timestamptz not null,status public.appointment_status not null default 'pending',price numeric(10,2) not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.commissions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,appointment_id uuid not null unique references public.appointments(id) on delete cascade,staff_id uuid not null references public.staff(id) on delete cascade,amount numeric(10,2) not null default 0,paid boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.customer_history(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,appointment_id uuid references public.appointments(id) on delete set null,tenant_id uuid not null references public.tenants(id) on delete cascade,event_type text not null,description text,created_at timestamptz not null default now());
create table if not exists public.verification_codes(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,whatsapp text not null,code text not null,expires_at timestamptz not null,consumed_at timestamptz,attempts integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id) on delete set null,tenant_id uuid references public.tenants(id) on delete set null,action text not null,entity text,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists appointments_shop_time_idx on public.appointments(shop_id,starts_at,ends_at); create index if not exists appointments_customer_idx on public.appointments(customer_id,starts_at desc);
create or replace function public.update_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','tenants','shops','staff','services','customers','appointments'] loop execute format('drop trigger if exists trg_%s_updated_at on public.%s',t,t); execute format('create trigger trg_%s_updated_at before update on public.%s for each row execute function public.update_updated_at()',t,t); end loop; end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,whatsapp,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.raw_user_meta_data->>'whatsapp',coalesce((new.raw_user_meta_data->>'role')::public.app_role,'customer')); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.check_appointment_conflict(p_shop uuid,p_barber uuid,p_start timestamptz,p_end timestamptz,p_ignore uuid default null) returns boolean language sql stable as $$ select exists(select 1 from public.appointments a where a.shop_id=p_shop and a.id is distinct from p_ignore and a.status not in ('cancelled','no_show') and a.starts_at<p_end and a.ends_at>p_start and (p_barber is null or a.barber_id=p_barber)); $$;
create or replace function public.prevent_appointment_conflict() returns trigger language plpgsql as $$ begin if new.status not in ('cancelled','no_show') and public.check_appointment_conflict(new.shop_id,new.barber_id,new.starts_at,new.ends_at,new.id) then raise exception 'Horário indisponível'; end if; return new; end $$;
drop trigger if exists trg_appointment_conflict on public.appointments; create trigger trg_appointment_conflict before insert or update on public.appointments for each row execute function public.prevent_appointment_conflict();
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='super_admin' and is_active); $$;
create or replace function public.is_tenant_member(tid uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_super_admin() or exists(select 1 from profiles where id=auth.uid() and tenant_id=tid and role in ('tenant_owner','shop_manager','barber','attendant')); $$;
alter table public.profiles enable row level security; alter table public.tenants enable row level security; alter table public.shops enable row level security; alter table public.staff enable row level security; alter table public.services enable row level security; alter table public.customers enable row level security; alter table public.appointments enable row level security; alter table public.commissions enable row level security; alter table public.customer_history enable row level security; alter table public.verification_codes enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_read on public.profiles for select using(id=auth.uid() or public.is_super_admin() or tenant_id=(select tenant_id from profiles where id=auth.uid())); create policy profiles_update on public.profiles for update using(id=auth.uid() or public.is_super_admin());
create policy tenants_read on public.tenants for select using(public.is_super_admin() or owner_id=auth.uid() or public.is_tenant_member(id)); create policy tenants_admin_write on public.tenants for all using(public.is_super_admin()) with check(public.is_super_admin());
create policy shops_read on public.shops for select using(public.is_super_admin() or public.is_tenant_member(tenant_id)); create policy shops_write on public.shops for all using(public.is_super_admin() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='tenant_owner' and p.tenant_id=shops.tenant_id)) with check(public.is_super_admin() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='tenant_owner' and p.tenant_id=shops.tenant_id));
create policy staff_read on public.staff for select using(public.is_super_admin() or public.is_tenant_member(tenant_id)); create policy staff_write on public.staff for all using(public.is_super_admin() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='tenant_owner' and p.tenant_id=staff.tenant_id)) with check(public.is_super_admin() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='tenant_owner' and p.tenant_id=staff.tenant_id));
create policy services_public_read on public.services for select using(is_active=true); create policy services_write on public.services for all using(public.is_super_admin() or public.is_tenant_member(tenant_id)) with check(public.is_super_admin() or public.is_tenant_member(tenant_id));
create policy customers_read on public.customers for select using(id=auth.uid() or public.is_super_admin() or exists(select 1 from appointments a where a.customer_id=customers.id and public.is_tenant_member(a.tenant_id))); create policy customers_self_write on public.customers for all using(id=auth.uid() or public.is_super_admin()) with check(id=auth.uid() or public.is_super_admin());
create policy appointments_read on public.appointments for select using(public.is_super_admin() or tenant_id=(select tenant_id from profiles where id=auth.uid()) or customer_id=auth.uid()); create policy appointments_insert on public.appointments for insert with check(public.is_super_admin() or customer_id=auth.uid() or public.is_tenant_member(tenant_id)); create policy appointments_update on public.appointments for update using(public.is_super_admin() or tenant_id=(select tenant_id from profiles where id=auth.uid()) or customer_id=auth.uid());
create policy commissions_read on public.commissions for select using(public.is_super_admin() or tenant_id=(select tenant_id from profiles where id=auth.uid()) or staff_id=auth.uid()); create policy history_read on public.customer_history for select using(public.is_super_admin() or customer_id=auth.uid() or public.is_tenant_member(tenant_id)); create policy audit_read on public.audit_logs for select using(public.is_super_admin() or tenant_id=(select tenant_id from profiles where id=auth.uid())); create policy verification_self on public.verification_codes for all using(user_id=auth.uid()) with check(user_id=auth.uid());
-- Execute supabase/seed.sql after this file.
